// Rings screen for the OP-1, in place of the phase engine's screen
// (docs/screen-interface.md):
//   - the PdScreen getter loads "rings.svg" (content/display/rings.svg,
//     generated by op1/gen_rings_svg.py) instead of "pd.svg";
//   - Init (PdScreen vtable +0x24) finds our elements and reads the colours;
//   - Update (+0x1c) runs once per frame while the screen shows: it sets the
//     elements from the knob values, then draws.
//
// Colours are copied from the SVG's own elements in their default state
// (ring0 lit, ring5 dim, model0 selected, model1 not...), so the style's byte
// order doesn't matter.
//
// The model and polyphony buttons show the build's model (OP1RINGS_MODEL)
// and "all" (6 voices) until model and polyphony select exist.

#include "op1/screen.h"

#include <cstdint>

#include "op1/op1.h"
#include "op1/screen_math.h"

#ifndef OP1RINGS_MODEL
#define OP1RINGS_MODEL 0
#endif

extern "C" void RingsScreenInit(void* self);
extern "C" void RingsScreenUpdate(void* self, int32_t ticks);

namespace {

// Firmware (docs/screen-interface.md §2-§4).
const uint32_t kNodeFind = 0x019eb8ac;        // (document, id, assert) -> node
const uint32_t kGetLineStyle = 0x01a3b854;    // (screen, id) -> RGBA bytes
const uint32_t kGetFillStyle = 0x01a3b96c;
const uint32_t kSetTransform = 0x019ead58;    // (node, const int32 m[9])
const uint32_t kScreenDraw = 0x01a3b4c8;      // (screen)
const uint32_t kDisplayedSlot = 0x01df4e38;   // synth instance on screen
const uint32_t kKnobs = 0xff8013c4;           // int16 knobs[8] per instance
const int32_t kNumSlots = 8;
const uint32_t kNodeVisible = 0x50;           // byte in a Node

typedef void* (*NodeFindFn)(void* document, const char* id, int32_t assert_missing);
typedef uint8_t* (*StyleFn)(void* screen, const char* id);
typedef void (*SetTransformFn)(void* node, const int32_t* m);
typedef void (*DrawFn)(void* screen);

void* Find(void* document, const char* id) {
  return reinterpret_cast<NodeFindFn>(kNodeFind)(document, id, 0);
}
uint8_t* LineStyle(void* screen, const char* id) {
  return reinterpret_cast<StyleFn>(kGetLineStyle)(screen, id);
}
uint8_t* FillStyle(void* screen, const char* id) {
  return reinterpret_cast<StyleFn>(kGetFillStyle)(screen, id);
}

void SetTranslate(void* node, int32_t tx, int32_t ty) {
  int32_t m[9] = { 0x400, 0, 0, 0, 0x400, 0, tx, ty, 0x400 };
  reinterpret_cast<SetTransformFn>(kSetTransform)(node, m);
}

void SetVisible(void* node, bool visible) {
  *reinterpret_cast<volatile uint8_t*>(reinterpret_cast<uintptr_t>(node) + kNodeVisible) =
      visible ? 1 : 0;
}

struct Colour {
  uint8_t rgba[4];
};

void Read(Colour* c, const uint8_t* style) {
  for (int32_t i = 0; i < 4; ++i) c->rgba[i] = style[i];
}

void Write(uint8_t* style, const Colour& c) {
  for (int32_t i = 0; i < 4; ++i) style[i] = c.rgba[i];
}

const char* const kRingIds[6] = { "ring0", "ring1", "ring2", "ring3", "ring4", "ring5" };
const char* const kModelBoxIds[6] = {
  "model0box", "model1box", "model2box", "model3box", "model4box", "model5box" };
const char* const kModelNumIds[6] = {
  "model0num", "model1num", "model2num", "model3num", "model4num", "model5num" };
const char* const kPolyBoxIds[3] = { "poly0box", "poly1box", "poly2box" };
const char* const kPolyDotsIds[3] = { "poly0dots", "poly1dots", "poly2dots" };
const char* const kNodeIds[3] = { "brightness", "damping", "posdot" };
const char* const kPluckIds[op1::kPluckVariants] = {
  "pluck0", "pluck1", "pluck2", "pluck3", "pluck4", "pluck5", "pluck6", "pluck7",
  "pluck8", "pluck9", "pluck10", "pluck11", "pluck12", "pluck13", "pluck14", "pluck15",
  "pluck16", "pluck17", "pluck18", "pluck19", "pluck20", "pluck21", "pluck22", "pluck23" };

bool ready;
uint8_t* ring_styles[6];
uint8_t* model_box_styles[6];
uint8_t* model_num_styles[6];
uint8_t* poly_box_styles[3];
uint8_t* poly_dots_line_styles[3];
uint8_t* poly_dots_fill_styles[3];
void* nodes[3];                         // brightness, damping, posdot
void* pluck_nodes[op1::kPluckVariants];
Colour ring_on, ring_off;
Colour box_on, box_off, num_on, num_off;
Colour dots_line_on, dots_line_off, dots_fill_on, dots_fill_off;

bool AllPresent(void* document, const char* const* ids, int32_t n) {
  for (int32_t i = 0; i < n; ++i) {
    if (!Find(document, ids[i])) return false;
  }
  return true;
}

}  // namespace

extern "C" void RingsScreenInit(void* self) {
  ready = false;
  void* document = *reinterpret_cast<void**>(self);
  if (!document) return;
  // GetLineStyle asserts on a missing id: check them all first, and leave
  // the screen static rather than crash if the SVG is wrong.
  if (!AllPresent(document, kRingIds, 6) || !AllPresent(document, kModelBoxIds, 6) ||
      !AllPresent(document, kModelNumIds, 6) || !AllPresent(document, kPolyBoxIds, 3) ||
      !AllPresent(document, kPolyDotsIds, 3) || !AllPresent(document, kNodeIds, 3) ||
      !AllPresent(document, kPluckIds, op1::kPluckVariants)) {
    return;
  }
  for (int32_t i = 0; i < 6; ++i) {
    ring_styles[i] = LineStyle(self, kRingIds[i]);
    model_box_styles[i] = LineStyle(self, kModelBoxIds[i]);
    // On a group, GetLineStyle gives every child the first child's style:
    // the glyph's parts share one colour anyway.
    model_num_styles[i] = LineStyle(self, kModelNumIds[i]);
  }
  for (int32_t i = 0; i < 3; ++i) {
    poly_box_styles[i] = LineStyle(self, kPolyBoxIds[i]);
    poly_dots_line_styles[i] = LineStyle(self, kPolyDotsIds[i]);
    poly_dots_fill_styles[i] = FillStyle(self, kPolyDotsIds[i]);
  }
  for (int32_t i = 0; i < 3; ++i) nodes[i] = Find(document, kNodeIds[i]);
  for (int32_t i = 0; i < op1::kPluckVariants; ++i) pluck_nodes[i] = Find(document, kPluckIds[i]);

  // The SVG's defaults: ring0 lit, ring5 dim; model0 and poly0 selected.
  Read(&ring_on, ring_styles[0]);
  Read(&ring_off, ring_styles[5]);
  Read(&box_on, model_box_styles[0]);
  Read(&box_off, model_box_styles[1]);
  Read(&num_on, model_num_styles[0]);
  Read(&num_off, model_num_styles[1]);
  Read(&dots_line_on, poly_dots_line_styles[0]);
  Read(&dots_line_off, poly_dots_line_styles[1]);
  Read(&dots_fill_on, poly_dots_fill_styles[0]);
  Read(&dots_fill_off, poly_dots_fill_styles[1]);
  ready = true;
}

extern "C" void RingsScreenUpdate(void* self, int32_t ticks) {
  (void)ticks;
  const int32_t slot = *reinterpret_cast<const volatile int32_t*>(kDisplayedSlot);
  if (ready && slot >= 0 && slot < kNumSlots) {
    const int16_t* knobs = reinterpret_cast<const int16_t*>(kKnobs + slot * 16);
    const op1::ScreenState s = op1::ComputeScreenState(knobs);
    for (int32_t i = 0; i < 6; ++i) {
      Write(ring_styles[i], i < s.lit_rings ? ring_on : ring_off);
    }
    SetTranslate(nodes[0], 0, s.brightness_ty);
    SetTranslate(nodes[1], 0, s.damping_ty);
    SetTranslate(nodes[2], s.posdot_tx, 0);
    for (int32_t i = 0; i < op1::kPluckVariants; ++i) SetVisible(pluck_nodes[i], i == s.pluck);
    for (int32_t i = 0; i < 6; ++i) {
      const bool on = i == OP1RINGS_MODEL;
      Write(model_box_styles[i], on ? box_on : box_off);
      Write(model_num_styles[i], on ? num_on : num_off);
    }
    // Polyphony "all": every button lit.
    for (int32_t i = 0; i < 3; ++i) {
      Write(poly_box_styles[i], box_on);
      Write(poly_dots_line_styles[i], dots_line_on);
      Write(poly_dots_fill_styles[i], dots_fill_on);
    }
  }
  // Update must draw (Screen::UpdateAll doesn't).
  reinterpret_cast<DrawFn>(kScreenDraw)(self);
}

namespace op1 {

// The file name the PdScreen getter passes to Screen::Screen.
extern const char kRingsSvgName[];
const char kRingsSvgName[] = "rings.svg";

const Patch kScreenPatches[kNumScreenPatches] = {
  // PdScreen getter 0x1a0cd50: R2.L = 0x2e40; R2.H = 0x018f ("pd.svg").
  { 0x01a0cd8e, kImm16Lo, 0x2e40, kRingsSvgName },
  { 0x01a0cd92, kImm16Hi, 0x018f, kRingsSvgName },
  // PdScreen vtable 0x191116c: Init (+0x24), Update (+0x1c).
  { 0x01911190, kWord32, 0x01a0cca0, reinterpret_cast<const void*>(&RingsScreenInit) },
  { 0x01911188, kWord32, 0x01a0c0a0, reinterpret_cast<const void*>(&RingsScreenUpdate) },
};

}  // namespace op1
